POST /hcmRestApi/resources/11.13.18.05/workers
REST-Framework-Version: 4
Content-Type: application/vnd.oracle.adf.resourceitem+json
Effective-Of: RangeStartDate=2019-06-02

{
  "names": [{ "LastName": "Martineau", "FirstName": "Alicia", "LegislationCode": "US" }],
  "emails": [{ "EmailType": "W1", "EmailAddress": "alicia.m@example.com", "PrimaryFlag": true }],
  "workRelationships": [{
    "LegalEmployerName": "Vision Corporation", "WorkerType": "E", "PrimaryFlag": true,
    "assignments": [{ "BusinessUnitName": "Vision Central", "ActionCode": "HIRE", "LocationId": 300100006480525 }]
  }]
}

updatedMin = lastProcessedEntry
page = 1
repeat {
  entries = GET /feed?updated-min=${updatedMin}&page-size=10&page=${page}&orderBy=updated:asc
  foreach entry { process; if ok lastProcessedEntry = entry.updatedDate else break }
  page++
} while (entries.size == 10)

define([], function () {
  'use strict';
  class PageModule {
    flattenWorkers(resp) {
      const rows = [];
      (resp.items || []).forEach(function (w) {
        const n = (w.names && w.names.items && w.names.items[0]) || {};
        ((w.workRelationships && w.workRelationships.items) || []).forEach(function (wr) {
          ((wr.assignments && wr.assignments.items) || []).forEach(function (a) {
            rows.push({ PersonNumber: w.PersonNumber, DisplayName: n.DisplayName, LegalEmployer: wr.LegalEmployerName,
              AssignmentNumber: a.AssignmentNumber, DepartmentName: a.DepartmentName, JobCode: a.JobCode, Status: a.AssignmentStatusType });
          });
        });
      });
      return rows;
    }
  }
  return PageModule;
});
